fun main() {
    val x = 0b1011_0110
    println(x and 0xF)
    println(x or 0x100)
    println(x xor 0xFF)
    println(x.inv())
    println(x shl 4)
    println(x shr 2)
    println(x.countOneBits())
    println(x.countLeadingZeroBits())
    println(x.countTrailingZeroBits())
    println(Integer.toBinaryString(x))
    println(x.toString(2).padStart(10, '0'))
    println(Integer.bitCount(255))
    println(0xFF.toByte())
    println(0x7F.toByte() + 1)
    println(x.rotateLeft(28))
    println(x.rotateRight(4))
    println(1L shl 62 or 1L)
    println((1L shl 63).toString())
    println(0xFFFFFFFFL and 0xFF00FF00L)
    println(Long.MAX_VALUE.countOneBits())
    println(Integer.highestOneBit(100))
    println(Integer.reverse(1))
    println(Integer.toHexString(-1))
    println("ff".toInt(16) + "101".toInt(2))
    println(Integer.parseInt("-7f", 16))
    var flags = 0
    for (i in listOf(1, 3, 5)) flags = flags or (1 shl i)
    println(flags)
    println((0..7).filter { flags and (1 shl it) != 0 })
    println(5.takeHighestOneBit() to 5.takeLowestOneBit())
    val b: Byte = 0x0F
    println(b.toInt() shl 4)
    println((b.toInt() and 0xFF).toString(2))
    println(1.toByte().toInt().inv())
    println(0x80000000.toInt())
}
